// Windance compact morning status report.
// The script performs live checks and sends the SMS through Node-RED's /codex/send-imessage endpoint.
msg.payload = "/usr/bin/python3 /Users/zuzu/bin/windance_morning_status_report.py";
return msg;

const allowed = ["AL", "HAL", "SAL", "Herald", "HERALD", "Odyssey", "TMA-1", "TMA-2", "ResWEB"];
const raw = String((msg.req && msg.req.query && msg.req.query.device) || "").trim();
let device = raw;
if (device.toUpperCase() === "HERALD") device = "Herald";
if (!allowed.includes(device)) {
    msg.statusCode = 400;
    msg.payload = {ok:false, error:"Unknown device"};
    return msg;
}
const status = global.get(`device_${device}_status`) || "Waiting...";
msg.payload = {ok:true, device, status};
return msg;

const isDown = msg.payload === false;
msg.status = isDown ? "down" : "up";
msg.pingMs = isDown ? null : Number(msg.payload);
msg.topic = msg.device;
msg.payload = isDown ? "Is Offline" : "Is UP";
global.set(`device_${msg.device}_status`, msg.payload);
return msg;

const kasa = "~/Library/Python/3.9/bin/kasa";
const host = "192.168.36.4";
const phone = "+16054401255";
const offSeconds = 25;

const safeDevice = String(msg.device || "Unknown").replace(/"/g, '\\"');

let smsText;
let kasaMsg = null;

if (msg.rebootAllowed && msg.kasaPlugName) {
    const rebootKey = `rebooting_${msg.device}`;
    if (flow.get(rebootKey)) {
        node.status({fill:"yellow", shape:"ring", text:`${msg.device} reboot already in progress`});
        return [null, null];
    }
    flow.set(rebootKey, true);
    flow.set(`pending_back_up_${msg.device}`, true);
    flow.set(`last_reboot_${msg.device}`, new Date().toISOString());

    const plug = String(msg.kasaPlugName).replace(/"/g, '\\"');
    kasaMsg = {
        payload: `${kasa} --host ${host} off --name "${plug}"; sleep ${offSeconds}; ${kasa} --host ${host} on --name "${plug}"`,
        topic: msg.device,
        device: msg.device
    };
    smsText = `${safeDevice} is DOWN. Power cycling Kasa plug "${plug}" now.`;
} else {
    smsText = `${safeDevice} is DOWN. No automatic Kasa reboot is configured for this device.`;
}

return [kasaMsg, sms(smsText)];

function sms(text) {
    const safe = String(text).replace(/"/g, '\\"');
    return {
        payload: `osascript -e 'tell application "Messages" to send "${safe}" to buddy "${phone}"'`,
        topic: msg.device,
        device: msg.device
    };
}

const phone = "+16054401255";
const pendingKey = `pending_back_up_${msg.device}`;
const rebootKey = `rebooting_${msg.device}`;

if (!flow.get(pendingKey)) return null;

flow.set(pendingKey, false);
flow.set(rebootKey, false);

const pingText = Number.isFinite(msg.pingMs) ? ` Ping: ${msg.pingMs} ms.` : "";
const text = `${msg.device} is back UP after Kasa reboot.${pingText}`;
const safe = text.replace(/"/g, '\\"');

msg.payload = `osascript -e 'tell application "Messages" to send "${safe}" to buddy "${phone}"'`;
return msg;

if (msg.device !== "ResWEB") return msg;

const key = "consecutive_down_ResWEB";
if (msg.status === "down") {
    const count = Number(flow.get(key) || 0) + 1;
    flow.set(key, count);
    msg.downCount = count;
    if (count < 3) {
        node.status({fill:"yellow", shape:"ring", text:`ResWEB: failure ${count}/3`});
        return null;
    }
    node.status({fill:"red", shape:"dot", text:`ResWEB: confirmed down (${count}/3)`});
} else {
    flow.set(key, 0);
    node.status({fill:"green", shape:"dot", text:"ResWEB: counter reset"});
}
return msg;

msg.payload = Math.round(Number(msg.payload) * 10) / 10;
global.set("sal_cpu", msg.payload + "%");
return msg;

let match = String(msg.payload || "").match(/(\d+)%/);
if (!match) return null;
let free = parseInt(match[1]);
msg.payload = 100 - free;

global.set("sal_ram", msg.payload + "%");

return msg;

let cpu = parseFloat(msg.payload);
if (!Number.isFinite(cpu)) return null;

msg.payload = Number(cpu.toFixed(1));

global.set("hal_cpu", msg.payload + "%");

return msg;

let parts = String(msg.payload || "").trim().split(",").map(x => x.trim());

if (parts.length < 4) return null;

let gpu = Number(parts[0]);
let vramUsed = Number(parts[1]);
let vramTotal = Number(parts[2]);
let temp = Number(parts[3]);

let vramPct = Math.round((vramUsed / vramTotal) * 100);

global.set("hal_gpu", gpu + "%");
global.set("hal_vram", vramPct + "%");
global.set("hal_gpu_temp", temp + "?C");

return [
    { payload: gpu },
    { payload: vramPct },
    { payload: temp }
];

const p = msg.payload || {};
let cpu = Number(p.cpu_percent);
if (!Number.isFinite(cpu)) return null;

cpu = Math.max(0, Math.min(100, Number(cpu.toFixed(1))));
msg.payload = cpu;
global.set("herald_cpu", cpu + "%");
return msg;

const lines = String(msg.payload || "").trim().split("\n");
if (lines.length < 2) return null;
const parts = lines[1].split(/\s+/);
const usedPercent = parts[4] || "0%";
const usedNumber = parseInt(usedPercent.replace("%",""));
msg.payload = {
    device: msg.device,
    usedPercent,
    usedNumber,
    filesystem: parts[0],
    size: parts[1],
    used: parts[2],
    available: parts[3]
};
msg.topic = msg.device;
return msg;

const phone = "+16054401255";
const p = msg.payload || {};
const text = `${p.device} disk usage is ${p.usedPercent} (${p.used} used of ${p.size}).`;
const safe = text.replace(/"/g, '\\"');
msg.payload = `osascript -e 'tell application "Messages" to send "${safe}" to buddy "${phone}"'`;
return msg;

const s = msg.payload || {};
const error = String(s.error || s.invalid || s.watchError || "").trim();
const needItems = Number(s.needTotalItems || 0);
const needBytes = Number(s.needBytes || 0);
const receiveOnly = Number(s.receiveOnlyTotalItems || 0);
let status = "UNKNOWN";

if (error) {
    status = `ERROR: ${error}`;
} else if (s.state === "syncing") {
    status = `Syncing (${needItems} items)`;
} else if (s.state === "scanning") {
    status = "Scanning";
} else if (needItems > 0) {
    const mib = Math.round(needBytes / 1048576);
    status = `Out of Sync (${needItems} items, ${mib} MiB)`;
} else if (receiveOnly > 0) {
    status = `Receive-only changes (${receiveOnly} items)`;
} else if (s.state === "idle") {
    status = "Up to Date";
} else {
    status = s.state || "UNKNOWN";
}

msg.payload = status;
msg.folder = msg.folderName;
msg.topic = msg.folderName;
msg.status = status;
global.set(`syncthing_${msg.folderName}_status`, status);
return msg;

const status = String(msg.status || msg.payload || "");
if (status === "Up to Date" || status === "Scanning" || status.startsWith("Syncing")) return null;
const key = `syncthing_alert_${msg.folder || "unknown"}`;
const last = global.get(key) || {};
const now = Date.now();
if (last.status === status && (now - last.at) < 3600000) return null;
global.set(key, { status, at: now });
return msg;

