Today: ${Math.round(d.temperature_2m_min?.[0])}?F-${Math.round(d.temperature_2m_max?.[0])}?F
Rain chance: ${d.precipitation_probability_max?.[0]}%
Max wind/gust: ${Math.round(d.wind_speed_10m_max?.[0])}/${Math.round(d.wind_gusts_10m_max?.[0])} mph`;
msg.payload = text;
return msg;

const phone = "+16054401255";
const safe = String(msg.payload || "").replace(/"/g, '\\"').replace(/\n/g, "\\n");
msg.payload = `osascript -e 'tell application "Messages" to send "${safe}" to buddy "${phone}"'`;
return msg;

const route = msg.route || "outbound";
msg.departureTime = msg.departureTime || new Date();
msg.truck = route === "return"
  ? { loaded: true, grossWeight: 116000, maxSafeWind: 30, maxSafeGust: 45 }
  : { loaded: false, grossWeight: 41000, maxSafeWind: 40, maxSafeGust: 55 };

const outbound = [
  { order:1, name:"Custer", lat:43.7667, lon:-103.5988, etaHours:0 },
  { order:2, name:"Orange Junction", lat:43.274, lon:-104.191, etaHours:2.5 },
  { order:3, name:"Casper", lat:42.8501, lon:-106.3252, etaHours:4.0 },
