  { order:5, name:"Ogden", lat:41.223, lon:-111.9738, etaHours:10.0 }
];

const ret = [
  { order:1, name:"Ogden", lat:41.223, lon:-111.9738, etaHours:0 },
  { order:2, name:"Rawlins", lat:41.7911, lon:-107.2387, etaHours:3.5 },
  { order:3, name:"Casper", lat:42.8501, lon:-106.3252, etaHours:6.0 }
];

msg.route = route;
msg.payload = route === "return" ? ret : outbound;
return msg;

let p = msg.payload;
msg.locationName = p.name;
msg.order = p.order;
msg.etaHours = p.etaHours;

let eta = new Date(msg.departureTime.getTime() + p.etaHours * 60 * 60 * 1000);
msg.eta = eta;
let start = eta.toISOString().slice(0, 10);

msg.url = `https://api.open-meteo.com/v1/forecast?latitude=${p.lat}&longitude=${p.lon}&hourly=temperature_2m,precipitation_probability,weather_code,wind_speed_10m,wind_gusts_10m&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch&timezone=America%2FDenver&start_date=${start}&end_date=${start}`;
return msg;

const codes = {
  0:"Clear",1:"Mainly clear",2:"Partly cloudy",3:"Overcast",45:"Fog",48:"Freezing fog",
  51:"Light drizzle",53:"Drizzle",55:"Heavy drizzle",61:"Light rain",63:"Rain",65:"Heavy rain",
  71:"Light snow",73:"Snow",75:"Heavy snow",80:"Rain showers",85:"Snow showers",95:"Thunderstorm"
};
let h = msg.payload.hourly || {};
let etaKey = msg.eta.toISOString().slice(0,13);
let index = (h.time || []).findIndex(t => t.slice(0,13) === etaKey);
if (index < 0) index = 0;

let temp = Math.round(h.temperature_2m?.[index] ?? 0);
let wind = Math.round(h.wind_speed_10m?.[index] ?? 0);
let gust = Math.round(h.wind_gusts_10m?.[index] ?? 0);
let pop = Math.round(h.precipitation_probability?.[index] ?? 0);
let code = h.weather_code?.[index];

let risk = "GO";
if (wind >= msg.truck.maxSafeWind || gust >= msg.truck.maxSafeGust) risk = "NO-GO";
else if (wind >= msg.truck.maxSafeWind - 5 || gust >= msg.truck.maxSafeGust - 5 || pop >= 50) risk = "CAUTION";

msg.payload = {
  order: msg.order,
  risk,
  text: `${msg.locationName}: ${risk} - ${temp}?F, ${codes[code] || "Unknown"}, wind/gust ${wind}/${gust} mph, precip ${pop}%`
};
return msg;

let items = msg.payload.sort((a,b) => a.order - b.order);
let rows = items.map(i => i.text).join("\n");
let worst = items.some(i => i.risk === "NO-GO") ? "NO-GO" :
            items.some(i => i.risk === "CAUTION") ? "CAUTION" : "GO";
let text = `Route weather: ${worst}\n${rows}`;
const phone = "+16054401255";
const safe = text.replace(/"/g, '\\"').replace(/\n/g, "\\n");
msg.payload = `osascript -e 'tell application "Messages" to send "${safe}" to buddy "${phone}"'`;
return msg;

const result = msg.payload ? msg.payload.trim() : "";
if (!result || result.startsWith("Error:")) return null;

const parts = result.split('|');
if (parts.length < 2) return null;

msg.payload = parts.slice(0, -1).join('|').trim();
msg.sender = parts[parts.length - 1].trim();
if (!msg.payload || !msg.sender) return null;

const normalized = msg.sender.replace(/[^0-9]/g, "");
const contacts = {
    "16054401255": { name: "William", phone: "+16054401255" },
    "16054403400": { name: "Shawn", phone: "+16054403400" }
};
const contact = contacts[normalized] || { name: "Unknown sender", phone: msg.sender };
msg.person = contact;
msg.senderName = contact.name;
msg.contactKey = normalized || msg.sender;
msg.replyTo = contact.phone || msg.sender;
msg.topic = String(msg.imessageRowid || Date.now());
return msg;

const ALLOWED_CONTACTS = new Set(["16054401255", "16054403400"]);
let text = String(msg.payload || "").trim();
if (!text) return null;
const senderKey = String(msg.contactKey || msg.sender || "").replace(/[^0-9]/g, "");
if (!ALLOWED_CONTACTS.has(senderKey)) {
    node.warn("Ignored iMessage command from an unapproved sender");
    return null;
}
msg.userText = text;
const lower = text.toLowerCase();
// Herald is now the central iMessage manager.  Previous Vega-prefixed
// messages should route to Herald too, rather than the old local Vega chat.
const isVega = false;
const isBillLookup = lower.startsWith("!bos") || lower.startsWith("!bill") || lower.includes("bill of sale") || lower.includes("bills of sale");
const isBusinessLookup = lower.startsWith("!biz") || lower.startsWith("!business") || lower.startsWith("!rag") || lower.includes("business folder") || lower.includes("in business") || lower.includes("from business");
const isMailReview = lower === "mail" || lower === "mail review" || lower === "mail status";
if (lower.startsWith("!search")) return [msg, null, null, null, null, null];
if (isBillLookup) return [null, msg, null, null, null, null];
if (isBusinessLookup) return [null, null, msg, null, null, null];
if (isMailReview) return [null, null, null, null, msg, null];
return [null, null, null, null, msg, null];

const cleanQuery = String(msg.userText || msg.payload || "").replace(/^!search\s+/i, "").trim();
msg.url = "https://api.search.brave.com/res/v1/web/search?q=" + encodeURIComponent(cleanQuery);
msg.headers = {
    "Accept": "application/json",
    "X-Subscription-Token": "${BRAVE_API_KEY}"
};
return msg;

function cleanText(text) {
    return String(text || "").replace(/<[^>]*>/g, "").replace(/&#x27;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, "&");
}
const results = msg.payload?.web?.results || [];
if (!results.length) {
    msg.payload = "I searched, but did not find useful results.";
    return msg;
}
msg.payload = results.slice(0, 3).map((r, i) =>
    `${i+1}. ${cleanText(r.title)}\n${cleanText(r.description || r.snippet || "")}\n${r.url || ""}`
).join("\n\n");
return msg;

const userText = String(msg.userText || msg.payload || "").trim();
if (!userText) return null;

const requestMsg = {...msg};
requestMsg.url = "http://192.168.36.21:8791/message";
requestMsg.method = "POST";
requestMsg.headers = { "Content-Type": "application/json" };
requestMsg.payload = {
    message: userText,
    user: msg.senderName || "william",
    channel: "max-imessage"
};

// No immediate "working on it" acknowledgement here.  Herald is the central
// manager now, so the iMessage reply should be Herald's actual answer.
return [null, requestMsg];

if (msg.error) {
    const detail = msg.error.message || String(msg.error);
    msg.payload = `Herald: I hit a routing error inside Max/Node-RED: ${detail}. No action was confirmed.`;
    return msg;
}

const res = msg.payload || {};
let answer =
    res.reply ||
    res.result?.summary ||
    res.result?.reply ||
    res.answer ||
    res.message?.content ||
    res.choices?.[0]?.message?.content ||
    "";

if (!answer && res.status === "blocked" && res.reason) {
    answer = `Blocked by policy: ${res.reason}`;
} else if (!answer && (res.status === "failed" || (Array.isArray(res.errors) && res.errors.length))) {
    const detail = Array.isArray(res.errors) && res.errors[0] ? (res.errors[0].message || JSON.stringify(res.errors[0])) : "unknown error";
    answer = `I hit an error and logged it: ${detail}.`;
} else if (!answer) {
    answer = "I got a response but could not parse it. I logged the bad response for repair.";
}

answer = String(answer).trim();
if (!/^(herald|max|iris|ledger|scout|archivist|athena|forge):/i.test(answer)) {
    answer = "Herald: " + answer;
}
msg.payload = answer;
return msg;

const raw = String(msg.payload || "").trim();
const recipient = String(msg.replyTo || msg.person?.phone || msg.sender || "").trim();
if (!raw || !recipient) {
    node.warn("Cannot send iMessage reply; raw=" + Boolean(raw) + ", recipient=" + (recipient || "(missing)"));
    return null;
}

// A single sender process owns every part, so Messages sends them in order.
const maxLen = 3500;
const chunks = [];
let remaining = raw;
while (remaining.length > maxLen) {
    let cut = remaining.lastIndexOf("\n", maxLen);
    if (cut < 1200) cut = remaining.lastIndexOf(". ", maxLen);
    if (cut < 1200) cut = remaining.lastIndexOf(" ", maxLen);
    if (cut < 1200) cut = maxLen;
    chunks.push(remaining.slice(0, cut).trim());
    remaining = remaining.slice(cut).trim();
}
if (remaining) chunks.push(remaining);
for (let i = 0; i < chunks.length; i++) {
    if (chunks.length > 1) chunks[i] = "(" + (i + 1) + "/" + chunks.length + ") " + chunks[i];
}
msg.payload = Buffer.from(JSON.stringify({to: recipient, chunks}), "utf8").toString("base64");
return msg;

msg.url = "http://192.168.36.10:5055/bills-of-sale";
msg.headers = {"Content-Type": "application/json"};
msg.payload = {
    sender: msg.sender || "",
    message: msg.userText || msg.payload || ""
};
return msg;

const res = msg.payload || {};
msg.payload = res.reply || res.error || "I could not complete the Bills of Sale lookup.";
return msg;

let text = String(msg.userText || msg.payload || "").trim();
text = text
    .replace(/^!(biz|business|rag)\b/i, "")
    .replace(/^\s+/, "");
msg.url = "http://192.168.36.10:5056/query";
msg.headers = {"Content-Type": "application/json"};
msg.payload = {
    question: text || msg.userText || msg.payload,
    top_k: 8
};
return msg;

const res = msg.payload || {};
if (res.answer) {
    const sources = Array.isArray(res.sources) ? res.sources.slice(0, 3).map(s => s.file).filter(Boolean) : [];
    msg.payload = sources.length ? res.answer + "\n\nSources: " + sources.join("; ") : res.answer;
} else {
    msg.payload = res.error || "I could not answer from the Business folder index.";
}
return msg;

const body = msg.payload || {};
const to = String(body.to || body.recipient || "+16054401255").trim();
let text = String(body.message || body.text || "").trim();
if (!text) {
    msg.statusCode = 400;
    msg.payload = {ok:false, error:"Missing message"};
    return [null, msg];
}
if (!text.toLowerCase().startsWith("codex:") && !text.toLowerCase().startsWith("max:")) {
    text = "Max: " + text;
}

// One sender process owns the entire delivery, preserving chronological order.
const maxLen = 3500;
const chunks = [];
let remaining = text;
while (remaining.length > maxLen) {
    let cut = remaining.lastIndexOf("\n", maxLen);
    if (cut < 1200) cut = remaining.lastIndexOf(". ", maxLen);
    if (cut < 1200) cut = remaining.lastIndexOf(" ", maxLen);
    if (cut < 1200) cut = maxLen;
    chunks.push(remaining.slice(0, cut).trim());
    remaining = remaining.slice(cut).trim();
}
if (remaining) chunks.push(remaining);
for (let i = 0; i < chunks.length; i++) {
    if (chunks.length > 1) chunks[i] = "(" + (i + 1) + "/" + chunks.length + ") " + chunks[i];
}
const encoded = Buffer.from(JSON.stringify({to, chunks}), "utf8").toString("base64");
node.send([{payload: encoded}, null]);
msg.payload = {ok:true, to, chunks:chunks.length, message:text};
return [null, msg];

let text = String(msg.userText || msg.payload || "").trim();
text = text
    .replace(/^hey\s+vega[,:]?\s*/i, "")
    .replace(/^hi\s+vega[,:]?\s*/i, "")
    .replace(/^vega[,:]?\s*/i, "")
    .trim();
if (!text) text = "Hello.";

const sender = String(msg.sender || "default");
const key = "vega_history_" + sender.replace(/[^a-zA-Z0-9_+-]/g, "_");
let history = global.get(key) || [];
history.push({ role: "user", content: text });
history = history.slice(-12);
global.set(key, history);

msg.vegaHistoryKey = key;
msg.url = "http://192.168.36.10:11434/api/chat";
msg.headers = {"Content-Type": "application/json"};
msg.payload = {
    model: "gemma4",
    stream: false,
    messages: [
        {
            role: "system",
            content: "You are Vega, William's local assistant reached through iMessage. Be warm, direct, practical, and concise. If you need Business-folder facts, tell William to ask with !biz or mention business folder. Do not claim to be Codex; you are Vega running locally through Max/Node-RED/Ollama."
        },
        ...history
    ]
};
return msg;

const res = msg.payload || {};
let answer =
    res?.message?.content ||
    res?.response ||
    res?.choices?.[0]?.message?.content ||
    "Vega: I got a response, but could not parse it.";
answer = String(answer).replace(/<channel\|?>/g, "").trim();
if (!answer.toLowerCase().startsWith("vega:")) {
    answer = "Vega: " + answer;
}

const key = msg.vegaHistoryKey;
if (key) {
    let history = global.get(key) || [];
    history.push({ role: "assistant", content: answer.replace(/^Vega:\s*/i, "") });
    global.set(key, history.slice(-12));
}

msg.payload = answer;
return msg;

const raw = String(msg.payload || "").trim();
if (!raw) return null;

// Expected format:
// ROWID|message text|sender
const parts = raw.split("|");
if (parts.length < 3) return null;

const rowid = Number(parts.shift());
const sender = parts.pop();
const text = parts.join("|").trim();

if (!Number.isFinite(rowid) || !text) return null;

const lastKey = "last_imessage_rowid";
const lastSeen = Number(global.get(lastKey) || 0);

// First run after deploy: learn the newest message, but do not process it.
