// Pi 5 begins thermal throttling near 80 C.  Require two samples (one minute)
// to avoid alerting on a single transient reading; recover below 72 C.
const stateKey = 'sam_cpu_thermal_alarm';
const state = global.get(stateKey) || {highCount: 0, active: false};
