if (gaugeMsg.payload >= 80) {
    state.highCount = Number(state.highCount || 0) + 1;
    if (!state.active && state.highCount >= 2) {
        state.active = true;
        const text = `Max: URGENT - SAM CPU is ${gaugeMsg.payload.toFixed(1)} C. It is at the Raspberry Pi thermal-throttling limit. Check the fan, airflow, and enclosure immediately.`;
        alertMsg = {...msg, payload: Buffer.from(JSON.stringify({to:'+16054401255', text}), 'utf8').toString('base64')};
    }
} else {
    state.highCount = 0;
    if (state.active && gaugeMsg.payload <= 72) {
        state.active = false;
        const text = `Max: SAM CPU temperature recovered to ${gaugeMsg.payload.toFixed(1)} C; the thermal alert is clear.`;
        alertMsg = {...msg, payload: Buffer.from(JSON.stringify({to:'+16054401255', text}), 'utf8').toString('base64')};
    }
}

